Thành phần Vai trò EAL (Environment Abstraction Layer) Khởi tạo môi trường: hugepage, gán thread vào core (lcore), dò và mở thiết bị PCI hoặc thiết bị trên SoC PMD (Poll Mode Driver) Driver của NIC chạy ở user space, ví dụ <code>net_ixgbe</code>, <code>net_i40e</code>, <code>net_ice</code>, <code>net_mlx5</code>, <code>net_dpaa2</code> <code>rte_mbuf</code> Cấu trúc mô tả một gói tin, tương tự <code>sk_buff</code> của kernel <code>rte_mempool</code> Vùng chứa các <code>rte_mbuf</code> cấp sẵn trong hugepage <code>rte_ring</code> Hàng đợi lock-free để chuyển gói giữa các core Thư viện khác Flow classification (<code>rte_flow</code>), QoS, crypto, BBDev (tăng tốc L1 cho RAN), eventdev <p>Vòng lặp xử lý điển hình của một core:</p> <pre><code>struct rte_mbuf *bufs[32];

for (;;) {
    uint16_t n = rte_eth_rx_burst(port, queue, bufs, 32);
    /* xử lý n gói */
    uint16_t sent = rte_eth_tx_burst(port, queue, bufs, n);
    for (uint16_t i = sent; i &lt; n; i++)
        rte_pktmbuf_free(bufs[i]);
}
</code></pre>

Luồng Chiều Ví dụ Đặc điểm Telemetry Thiết bị → cloud Nhiệt độ, điện áp pin, trạng thái Nhiều, nhỏ, định kỳ; chấp nhận mất vài mẫu Command Cloud → thiết bị Bật relay, khởi động lại Ít, cần xác nhận, thiết bị có thể đang ngủ Configuration / State Hai chiều Chu kỳ gửi, ngưỡng cảnh báo Cloud lưu "trạng thái mong muốn", thiết bị báo "trạng thái thực tế" (device shadow / device twin) Firmware Cloud → thiết bị Bản cập nhật rootfs, ứng dụng Lớn, cần ký số, cần rollback. Xem OTA Update Log / diagnostic Thiết bị → cloud Log lỗi, core dump Theo yêu cầu, có thể lớn <p>Mô hình device shadow giải quyết vấn đề thiết bị không luôn online: cloud ghi giá trị <code>desired</code>, khi thiết bị kết nối lại thì đọc phần chênh lệch, áp dụng rồi cập nhật <code>reported</code>.</p> <pre><code>{
  "desired":  { "report_interval_s": 60 },
  "reported": { "report_interval_s": 300, "fw": "1.4.2" }
}
</code></pre>

Struct Ai sở hữu Vai trò <code>struct clk</code> core, cấp cho từng consumer Handle per-consumer: mỗi lần <code>clk_get()</code> tạo một <code>struct clk</code> mới, chứa <code>min_rate</code>/<code>max_rate</code> riêng. Nhiều <code>struct clk</code> → 1 <code>clk_core</code>. <code>struct clk_core</code> core (private trong <code>clk.c</code>) Node trong cây: <code>parent</code>, <code>children</code>, <code>parents[]</code>, <code>rate</code>, <code>req_rate</code>, <code>enable_count</code>, <code>prepare_count</code>, <code>protect_count</code>, <code>flags</code>, <code>orphan</code>, <code>accuracy</code>, <code>phase</code>, <code>duty</code>, notifier. <code>struct clk_hw</code> provider (nhúng trong struct phần cứng) Cầu nối: provider dùng <code>container_of()</code> để lấy lại struct riêng; chứa <code>hw-&gt;init</code> (chỉ dùng lúc đăng ký). <p>Provider mô tả clock lúc đăng ký bằng <code>struct clk_init_data</code>. Nên dùng <code>parent_data</code> (<code>.fw_name</code> khớp <code>clock-names</code> của chính provider node, hoặc <code>.index</code>) hoặc <code>parent_hws</code> thay vì <code>parent_names</code>, vì tra cứu theo chuỗi toàn cục dễ vỡ và phụ thuộc thứ tự probe.</p> <pre><code>struct clk_init_data {
    const char      *name;
    const struct clk_ops    *ops;
    /* Chỉ dùng MỘT trong ba cách mô tả parent: */
    const char      * const *parent_names;  /* legacy */
    const struct clk_parent_data    *parent_data;   /* khuyến nghị */
    const struct clk_hw **parent_hws;       /* parent cùng driver */
    u8          num_parents;
    unsigned long       flags;
};
</code></pre>

include/uapi/vux_demo.h<pre><code>/* SPDX-License-Identifier: GPL-2.0 WITH Linux-syscall-note */
#ifndef _UAPI_VUX_DEMO_H
#define _UAPI_VUX_DEMO_H

#include &lt;linux/ioctl.h&gt;
#include &lt;linux/types.h&gt;

#define VUX_DEMO_BUF_SIZE   4096

enum vux_demo_mode {
    VUX_DEMO_MODE_NORMAL = 0,
    VUX_DEMO_MODE_UPPER  = 1,   /* chuyển dữ liệu ghi vào thành chữ hoa */
};

struct vux_demo_config {
    __u32 mode;     /* enum vux_demo_mode */
    __u32 reserved;     /* phải bằng 0, dành cho mở rộng sau này */
};

struct vux_demo_stats {
    __u64 bytes_read;
    __u64 bytes_written;
};

#define VUX_DEMO_IOC_MAGIC  0xD5

#define VUX_DEMO_RESET      _IO(VUX_DEMO_IOC_MAGIC, 0x00)
#define VUX_DEMO_GET_CONFIG _IOR(VUX_DEMO_IOC_MAGIC, 0x01, struct vux_demo_config)
#define VUX_DEMO_SET_CONFIG _IOW(VUX_DEMO_IOC_MAGIC, 0x02, struct vux_demo_config)
#define VUX_DEMO_GET_STATS  _IOR(VUX_DEMO_IOC_MAGIC, 0x03, struct vux_demo_stats)

#endif /* _UAPI_VUX_DEMO_H */
</code></pre>

vux_demo.c<pre><code>// SPDX-License-Identifier: GPL-2.0
#include &lt;linux/ctype.h&gt;
#include &lt;linux/fs.h&gt;
#include &lt;linux/miscdevice.h&gt;
#include &lt;linux/module.h&gt;
#include &lt;linux/mutex.h&gt;
#include &lt;linux/uaccess.h&gt;

#include "include/uapi/vux_demo.h"

struct vux_demo {
    struct mutex lock;      /* bảo vệ toàn bộ các trường bên dưới */
    char buf[VUX_DEMO_BUF_SIZE];
    size_t len;         /* số byte hợp lệ trong buf */
    struct vux_demo_config cfg;
    struct vux_demo_stats stats;
};

static struct vux_demo vdev = {
    .lock = __MUTEX_INITIALIZER(vdev.lock),
};

static ssize_t vux_demo_read(struct file *file, char __user *ubuf,
                 size_t count, loff_t *ppos)
{
    ssize_t ret;

    mutex_lock(&amp;vdev.lock);
    if (*ppos &gt;= vdev.len) {
        ret = 0;            /* EOF */
        goto out;
    }
    count = min_t(size_t, count, vdev.len - *ppos);
    if (copy_to_user(ubuf, vdev.buf + *ppos, count)) {
        ret = -EFAULT;
        goto out;
    }
    *ppos += count;
    vdev.stats.bytes_read += count;
    ret = count;
out:
    mutex_unlock(&amp;vdev.lock);
    return ret;
}

static ssize_t vux_demo_write(struct file *file, const char __user *ubuf,
                  size_t count, loff_t *ppos)
{
    ssize_t ret;
    size_t i;

    if (*ppos &gt;= VUX_DEMO_BUF_SIZE)
        return -ENOSPC;
    count = min_t(size_t, count, VUX_DEMO_BUF_SIZE - *ppos);

    mutex_lock(&amp;vdev.lock);
    if (copy_from_user(vdev.buf + *ppos, ubuf, count)) {
        ret = -EFAULT;
        goto out;
    }
    if (vdev.cfg.mode == VUX_DEMO_MODE_UPPER)
        for (i = 0; i &lt; count; i++)
            vdev.buf[*ppos + i] = toupper(vdev.buf[*ppos + i]);
    *ppos += count;
    vdev.len = max_t(size_t, vdev.len, *ppos);
    vdev.stats.bytes_written += count;
    ret = count;
out:
    mutex_unlock(&amp;vdev.lock);
    return ret;
}

static long vux_demo_ioctl(struct file *file, unsigned int cmd,
               unsigned long arg)
{
    void __user *argp = (void __user *)arg;
    struct vux_demo_config cfg;
    struct vux_demo_stats stats;

    switch (cmd) {
    case VUX_DEMO_RESET:
        mutex_lock(&amp;vdev.lock);
        vdev.len = 0;
        memset(&amp;vdev.stats, 0, sizeof(vdev.stats));
        mutex_unlock(&amp;vdev.lock);
        return 0;

    case VUX_DEMO_GET_CONFIG:
        mutex_lock(&amp;vdev.lock);
        cfg = vdev.cfg;
        mutex_unlock(&amp;vdev.lock);
        if (copy_to_user(argp, &amp;cfg, sizeof(cfg)))
            return -EFAULT;
        return 0;

    case VUX_DEMO_SET_CONFIG:
        if (copy_from_user(&amp;cfg, argp, sizeof(cfg)))
            return -EFAULT;
        if (cfg.mode &gt; VUX_DEMO_MODE_UPPER || cfg.reserved)
            return -EINVAL;
        mutex_lock(&amp;vdev.lock);
        vdev.cfg = cfg;
        mutex_unlock(&amp;vdev.lock);
        return 0;

    case VUX_DEMO_GET_STATS:
        mutex_lock(&amp;vdev.lock);
        stats = vdev.stats;
        mutex_unlock(&amp;vdev.lock);
        if (copy_to_user(argp, &amp;stats, sizeof(stats)))
            return -EFAULT;
        return 0;

    default:
        return -ENOTTY;
    }
}

static const struct file_operations vux_demo_fops = {
    .owner      = THIS_MODULE,
    .read       = vux_demo_read,
    .write      = vux_demo_write,
    .llseek     = default_llseek,
    .unlocked_ioctl = vux_demo_ioctl,
    .compat_ioctl   = compat_ptr_ioctl,
};

static struct miscdevice vux_demo_misc = {
    .minor  = MISC_DYNAMIC_MINOR,
    .name   = "vux_demo",
    .fops   = &amp;vux_demo_fops,
    .mode   = 0666,
};

module_misc_device(vux_demo_misc);

MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("Demo character device: read/write and ioctl");
</code></pre> <p>Một vài điểm đáng chú ý:</p> <ul> <li>Chỉ có một instance, nên trạng thái để trong biến toàn cục <code>vdev</code>, bảo vệ bằng một mutex. Mutex (không phải spinlock) cho phép gọi <code>copy_*_user()</code> trong khi giữ khóa.</li> <li><code>read</code> trả về <code>0</code> khi <code>*ppos</code> chạm cuối dữ liệu, nên <code>cat /dev/vux_demo</code> dừng đúng chỗ.</li> <li>Trong <code>ioctl</code>, <code>GET_*</code> copy trạng thái ra biến cục bộ dưới mutex rồi mới gọi <code>copy_to_user()</code>; <code>SET_CONFIG</code> copy và kiểm tra trước, chỉ khóa khi cập nhật.</li> <li>Các struct UAPI đều không có padding và có cùng kích thước trên 32/64 bit, nên dùng thẳng <code>compat_ptr_ioctl</code>.</li> <li><code>.mode = 0666</code> để test không cần root. Driver thật nên hạn chế quyền và để udev cấp cho đúng nhóm người dùng.</li> </ul>

vux_demo_test.c<pre><code>#include &lt;errno.h&gt;
#include &lt;fcntl.h&gt;
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;
#include &lt;sys/ioctl.h&gt;
#include &lt;unistd.h&gt;

#include "include/uapi/vux_demo.h"

#define DEV "/dev/vux_demo"

int main(void)
{
    struct vux_demo_config cfg = { .mode = VUX_DEMO_MODE_UPPER };
    struct vux_demo_stats stats;
    const char *msg = "hello kernel";
    char buf[64] = { 0 };
    int fd;

    fd = open(DEV, O_RDWR);
    if (fd &lt; 0) {
        perror("open " DEV);
        return 1;
    }

    if (ioctl(fd, VUX_DEMO_RESET) &lt; 0 ||
        ioctl(fd, VUX_DEMO_SET_CONFIG, &amp;cfg) &lt; 0) {
        perror("ioctl");
        return 1;
    }

    if (write(fd, msg, strlen(msg)) &lt; 0) {
        perror("write");
        return 1;
    }
    lseek(fd, 0, SEEK_SET);
    if (read(fd, buf, sizeof(buf) - 1) &lt; 0) {
        perror("read");
        return 1;
    }
    printf("read back : %s\n", buf);

    if (ioctl(fd, VUX_DEMO_GET_STATS, &amp;stats) &lt; 0) {
        perror("ioctl GET_STATS");
        return 1;
    }
    printf("stats     : read=%llu written=%llu\n",
           (unsigned long long)stats.bytes_read,
           (unsigned long long)stats.bytes_written);

    /* Lệnh không tồn tại: driver trả về -ENOTTY */
    if (ioctl(fd, _IO(VUX_DEMO_IOC_MAGIC, 0x7f)) &lt; 0)
        printf("bad cmd   : %s\n", strerror(errno));

    /* Con trỏ không hợp lệ: copy_to_user() thất bại, driver trả về -EFAULT */
    if (ioctl(fd, VUX_DEMO_GET_STATS, (void *)1) &lt; 0)
        printf("bad ptr   : %s\n", strerror(errno));
    if (ioctl(fd, VUX_DEMO_GET_STATS, (void *)0xffffffff81000000UL) &lt; 0)
        printf("kernel ptr: %s\n", strerror(errno));

    close(fd);
    return 0;
}
</code></pre>
